definition.script:
pipeline {
  agent any

  options {
    timestamps()
    timeout(time: 15, unit: 'MINUTES')
  }

  environment {
    NODE_ENV = 'test'
    CI = 'true'
  }

  stages {
    stage('Setup Test Environment') {
      steps {
        echo 'Starting PostgreSQL test database...'
        dir('/Users/pedroalves/Documents/nerv3/micro/auth-min') {
          sh 'docker-compose -f docker-compose.test.yml up -d postgres-test'
          sh 'sleep 10'
        }
      }
    }

    stage('Install Dependencies') {
      steps {
        echo 'Installing dependencies...'
        dir('/Users/pedroalves/Documents/nerv3/micro/auth-min') {
          sh 'npm ci'
        }
      }
    }

    stage('Generate Prisma Client') {
      steps {
        echo 'Generating Prisma clients...'
        dir('/Users/pedroalves/Documents/nerv3/micro/auth-min') {
          sh 'npm run prisma:generate'
          sh 'npm run prisma:generate:test'
        }
      }
    }

    stage('Setup Database') {
      steps {
        echo 'Setting up test database...'
        dir('/Users/pedroalves/Documents/nerv3/micro/auth-min') {
          sh 'DATABASE_URL="postgresql://auth_test_user:auth_test_password@localhost:8239/auth_test_db" npx prisma db push --skip-generate'
        }
      }
    }

    stage('Run Tests') {
      steps {
        echo 'Running all tests...'
        dir('/Users/pedroalves/Documents/nerv3/micro/auth-min') {
          sh 'npm run test'
          sh 'npm run test:e2e'
        }
      }
    }
  }

  post {
    always {
      echo 'Stopping test services...'
      dir('/Users/pedroalves/Documents/nerv3/micro/auth-min') {
        sh 'docker-compose -f docker-compose.test.yml down || true'
      }
      echo 'Pipeline completed!'
    }
    success {
      echo '✅ All tests passed!'
    }
    failure {
      echo '❌ Pipeline failed!'
    }
  }
}
